import{_ as e,o as i,c as r,a2 as t}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"같은 선택이 같은 결과가 되나","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Save-and-Determinism.md","filePath":"rules/Save-and-Determinism.md"}'),l={name:"rules/Save-and-Determinism.md"};function s(o,a,n,d,h,m){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="같은-선택이-같은-결과가-되나" tabindex="-1">같은 선택이 같은 결과가 되나 <a class="header-anchor" href="#같은-선택이-같은-결과가-되나" aria-label="Permalink to &quot;같은 선택이 같은 결과가 되나&quot;">​</a></h1><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/isometric-grammar.svg?raw=true" alt="저장 뒤에도 칸에 누가 서 있고 어느 쪽을 보며 어디까지 보이는지 그대로 이어지는지"></p><h2 id="다시-돌려도-같은-세계" tabindex="-1">다시 돌려도 같은 세계 <a class="header-anchor" href="#다시-돌려도-같은-세계" aria-label="Permalink to &quot;다시 돌려도 같은 세계&quot;">​</a></h2><p>같은 시작값과 선택 기록으로 다시 돌리면 같은 세계 상태와 사건 기록의 검사값이 나와야 합니다. 무작위 값은 전투, 조우, 세계 사건처럼 쓰임새별로 나눠, 한 시스템의 처리 순서가 다른 시스템의 결과를 흔들지 않게 합니다.</p><h2 id="사건-원장" tabindex="-1">사건 원장 <a class="header-anchor" href="#사건-원장" aria-label="Permalink to &quot;사건 원장&quot;">​</a></h2><p>모든 상태 변경은 다음을 기록합니다.</p><ul><li>원인 ID와 명령</li><li>세계 시간</li><li>변경 주체와 대상</li><li>변경 전후 요약 해시</li><li>규칙과 콘텐츠 버전</li></ul><p>이 원장을 통해 “왜 노선이 봉쇄되었는가”, “왜 물가가 올랐는가”, “왜 인물이 세력을 떠났는가”를 설명할 수 있습니다. 면담·거래·후계 지지처럼 인물에게 한 일은 <a href="/world/Heirs-Names-and-World-Ledger.html">후계, 이름 로스터, 세계 원장</a>의 미시 줄로만 남고, 합이 임계를 넘을 때 여기 세계 사건이 됩니다. 성명을 고르는 난수는 인물 스트림만 씁니다.</p><h2 id="저장-파일에-담는-것" tabindex="-1">저장 파일에 담는 것 <a class="header-anchor" href="#저장-파일에-담는-것" aria-label="Permalink to &quot;저장 파일에 담는 것&quot;">​</a></h2><p>저장 파일에는 판본이 붙은 세계 상태, 명령·사건의 위치, 콘텐츠 판본과 진행 중인 전투의 중간 지점을 담습니다. 먼저 임시 파일에 쓰고 검사값을 확인한 뒤 원본과 바꿉니다.</p><p>지원하지 않는 버전, 잘린 파일, 잘못된 체크섬은 조용히 읽지 않습니다. 명확한 오류를 반환하고 이전 백업을 보존합니다.</p><h2 id="전투-중-저장하는-때" tabindex="-1">전투 중 저장하는 때 <a class="header-anchor" href="#전투-중-저장하는-때" aria-label="Permalink to &quot;전투 중 저장하는 때&quot;">​</a></h2><ul><li>전투 컨텍스트 발행 전</li><li>전투 턴이 끝난 중간 지점</li><li>결과 정산 완료 뒤</li></ul><p>중간 저장을 읽을 때 캠페인을 다시 조회하지 않고 저장된 불변 컨텍스트와 전투 명령 기록을 복원합니다.</p>',14)])])}const u=e(l,[["render",s]]);export{p as __pageData,u as default};
